import json, numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
from PIL import Image
S=json.load(open('/app/output/spec.json'))
P=np.array(S['arm']['position_m']); AX=np.array(S['arm']['axis']); EE=np.array(S['arm']['end_effector']['position_m'])
def fk(q, point=EE):
    R=np.eye(3); t=np.zeros(3)
    for p,ax,a in zip(P,AX,q):
        rot=Rotation.from_rotvec(ax*a).as_matrix()
        t=t+R@(p-rot@p); R=R@rot
    return R@point+t,R

def ik(pos,q,orientation=np.diag([1,-1,-1])):
    def fun(x):
        p,R=fk(x)
        return np.r_[(p-pos)*5, Rotation.from_matrix(orientation.T@R).as_rotvec()]
    lo=np.array([-np.inf,-2.24,-np.inf,-2.57,-np.inf,-2.09,-np.inf]); hi=-lo
    res=least_squares(fun,np.clip(q,lo+1e-5,hi-1e-5),bounds=(lo,hi),max_nfev=500)
    if np.linalg.norm(fun(res.x))>.02: print('IK residual',fun(res.x))
    return res.x
class Driver:
    def __init__(self): self.r=Robot(); self.o=self.r.observe(images=False); self.grip=0
    def save(self,name='view'):
        self.o=self.r.observe();
        for k,v in self.o['images'].items(): Image.fromarray(v).save('/app/output/'+name+'_'+k+'.png')
        np.savez('/app/output/'+name+'_depth.npz',**self.o.get('depth',{}))
        json.dump(self.o['proprio'],open('/app/output/'+name+'_proprio.json','w')); print('OBS',self.o['step'],self.o['proprio'],'DONE',self.o['done'],self.o['reason'])
    def joints(self,target,grip=None,maxsteps=100):
        if grip is not None:self.grip=grip
        for _ in range(maxsteps):
            q=np.array(self.o['proprio']['arm_pos']); err=target-q
            if np.max(abs(err))<.003: break
            a=np.r_[np.zeros(3),np.clip(err,-.08,.08),self.grip]
            self.o=self.r.step('delta',a.tolist(),images=False)
            if self.o['done']: print('DONE',self.o['reason']);return
    def pose(self,pos,grip=None):
        q=np.array(self.o['proprio']['arm_pos']); self.joints(ik(np.array(pos),q),grip)
    def hold(self,n=10,grip=None):
        if grip is not None:self.grip=grip
        self.o=self.r.step('delta',[([0]*10+[self.grip]) for _ in range(n)],images=False)
    def base(self,x,y,yaw=0):
        target=np.array([x,y,yaw])
        for _ in range(100):
            err=target-np.array(self.o['proprio']['base_pose']); a=err.copy(); a[:2]*=min(1,.08/max(np.linalg.norm(a[:2]),1e-9));a[2]=np.clip(a[2],-.08,.08)
            if max(abs(err))<.002:break
            self.o=self.r.step('delta',np.r_[a,np.zeros(7),self.grip].tolist(),images=False)
            if self.o['done']:break
if __name__=='__main__':
    d=Driver(); print('FK',fk(d.o['proprio']['arm_pos'])); d.pose([.5,0,1.25]);d.save('survey')
