from gen import *
import cv2

def cloud(o):
    cam=S['cameras']['robot_wrist']; cp=cam['pose']; p,R=fk(o['proprio']['arm_pos'],np.array(cp['position_m']))
    bp=o['proprio']['base_pose']; BR=Rotation.from_euler('z',bp[2]).as_matrix(); p=BR@p+np.r_[bp[:2],0]; R=BR@R
    dep=o['depth']['robot_wrist']; h,w=dep.shape; f=h/2/np.tan(np.deg2rad(cam['fovy_deg']/2)); u,v=np.meshgrid(np.arange(w),np.arange(h))
    local=dep[:,:,None]*(np.array(cp['forward'])+(u[:,:,None]-(w-1)/2)/f*np.array(cp['right'])+((h-1)/2-v[:,:,None])/f*np.array(cp['up']))
    return local@R.T+p

def objects(o,verbose=True):
    im=o['images']['robot_wrist']; hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV); c=cloud(o); H=hsv[:,:,0]; sat=hsv[:,:,1]; val=hsv[:,:,2]
    masks={'red':((H<10)|(H>170)),'green':((H>35)&(H<90)),'blue':((H>95)&(H<135)),'yellow':((H>20)&(H<35))}
    out={}
    for name,mask in masks.items():
        mask=(mask&(sat>100)&(val>25)).astype('uint8');n,l,st,cen=cv2.connectedComponentsWithStats(mask)
        comps=[]
        for i in range(1,n):
            if st[i,4]<10:continue
            pts=c[l==i]; comps.append({'pixels':int(st[i,4]),'uv':cen[i].tolist(),'median':np.median(pts,axis=0).tolist(),'min':pts.min(0).tolist(),'max':pts.max(0).tolist()})
        out[name]=comps
    if verbose:print(json.dumps(out,indent=2))
    return out
if __name__=='__main__':
    d=Driver();d.o=d.r.observe();objects(d.o)
